        </div>
    </div>

    <!-- 模型列表 -->
    <div class="card">
        <div class="card-title">🎮 可用模型 <span style="font-weight:400;color:#556;font-size:12px" id="modelCount"></span></div>
        <div id="modelList">加载中...</div>
    </div>

    <div class="footer">
        API中转站 v3.0 · 所有请求走本地 <code>127.0.0.1:__PORT__</code> · Token不会泄露到外网
    </div>
</div>

<script>
const BASE = '__BASE_URL__';
const TOKEN = '__TOKEN__';
let isOnline = false;

async function checkStatus() {
    try {
        const r = await fetch(BASE + '/health', {signal: AbortSignal.timeout(2000)});
        if (r.ok) {
            const d = await r.json();
            isOnline = true;
            document.getElementById('statusDot').className = 'status-dot online';
            document.getElementById('statusText').className = 'status-text online';
            document.getElementById('statusText').textContent = '🟢 运行中';
            document.getElementById('statusDetail').textContent = `监听端口 __PORT__ · ${d.models.length}个模型就绪`;
            document.getElementById('btnStart').disabled = true;
            document.getElementById('btnStop').disabled = false;
            renderModels(d.providers, d.models);
        }
    } catch(e) {
        isOnline = false;
        document.getElementById('statusDot').className = 'status-dot';
        document.getElementById('statusText').className = 'status-text offline';
        document.getElementById('statusText').textContent = '⚪ 已停止';
        document.getElementById('statusDetail').textContent = '服务未运行，点击启动按钮开始';
        document.getElementById('btnStart').disabled = false;
        document.getElementById('btnStop').disabled = true;
    }
}

function renderModels(providers, models) {
    document.getElementById('modelCount').textContent = `(${models.length}个)`;
    let html = '';
    for (const m of models) {
        // 从模型名推断provider（简化）
        const prov = m.startsWith('sf-') ? 'siliconflow' : 
                     m.startsWith('deepseek') ? 'deepseek' : 'other';
        const active = providers[prov] && providers[prov] !== '0个Key';
        html += `<div class="model-item">
            <div class="model-dot ${active ? 'active' : 'inactive'}"></div>
            <div class="model-name">${m}</div>
            <div class="model-arrow">→</div>
            <div class="model-dest">${m}</div>
            <div class="model-provider">[${prov}] ${active ? '🟢' : '⚪'}</div>
        </div>`;
    }
    document.getElementById('modelList').innerHTML = html;
}

async function doStart() {
    document.getElementById('statusText').textContent = '⏳ 启动中...';
    document.getElementById('statusText').className = 'status-text checking';
    document.getElementById('btnStart').disabled = true;
    document.getElementById('btnStop').disabled = true;

    try {
        const r = await fetch(BASE + '/admin/start', {method:'POST', signal:AbortSignal.timeout(5000)});
        const d = await r.json();
        if (d.status === 'started') {
            setTimeout(checkStatus, 2000);
        }
    } catch(e) {
        // 启动请求本身可能失败（服务还没起），等几秒再检查
        setTimeout(checkStatus, 3000);
    }
}

async function doStop() {
    if (!confirm('确定要停止中转服务吗？')) return;
    try {
        await fetch(BASE + '/admin/stop', {method:'POST', signal:AbortSignal.timeout(3000)});
    } catch(e) {}
    setTimeout(checkStatus, 1500);
}

async function doRestart() {
    document.getElementById('statusText').textContent = '⏳ 重启中...';
    document.getElementById('statusText').className = 'status-text checking';
    document.getElementById('btnStart').disabled = true;
    document.getElementById('btnStop').disabled = true;
    try {
        await fetch(BASE + '/admin/restart', {method:'POST', signal:AbortSignal.timeout(3000)});
    } catch(e) {}
    setTimeout(checkStatus, 5000);
}

// 首次检查 & 定时刷新
checkStatus();
setInterval(checkStatus, 5000);
</script>
</body>
</html>"""

# 替换模板变量
DASHBOARD_HTML = DASHBOARD_HTML.replace("__BASE_URL__", BASE_URL)
DASHBOARD_HTML = DASHBOARD_HTML.replace("__PORT__", str(PORT))
DASHBOARD_HTML = DASHBOARD_HTML.replace("__TOKEN__", ACCESS_TOKEN)


# ====== HTTP请求处理器 ======
class RelayHandler(BaseHTTPRequestHandler):
    config = None
    upstream_keys = {}
    model_routes = {}
    key_index = {}
    _lock = threading.Lock()

    @classmethod
    def load_cfg(cls):
        if cls.config is None or True:  # 每次都重新加载，支持热更新
            try:
                with open(CONFIG_PATH, "r", encoding="utf-8") as f:
                    cls.config = json.load(f)
                cls.upstream_keys = cls.config["upstream_keys"]
                cls.model_routes = cls.config["model_routes"]
            except:
                if cls.config is None:
                    cls.config = {}
                    cls.upstream_keys = {}
                    cls.model_routes = {}

    @classmethod
    def get_key(cls, provider):
        with cls._lock:
            keys = cls.upstream_keys.get(provider, [])
            if not keys: return None
            idx = cls.key_index.get(provider, 0)
            cls.key_index[provider] = (idx + 1) % len(keys)
            return keys[idx]

    def check_auth(self):
        auth = self.headers.get("Authorization", "")
        return auth.replace("Bearer ", "") == ACCESS_TOKEN

    def _send_json(self, data, code=200):
        self.send_response(code)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Access-Control-Allow-Origin", "*")
        self.end_headers()
        self.wfile.write(json.dumps(data, ensure_ascii=False).encode())

    def _send_html(self, html, code=200):
        self.send_response(code)
        self.send_header("Content-Type", "text/html; charset=utf-8")
        self.end_headers()
        self.wfile.write(html.encode())

    def _read_body(self):
        length = int(self.headers.get("Content-Length", 0))
        return json.loads(self.rfile.read(length)) if length > 0 else {}

    # ====== 路由 ======
    def do_GET(self):
        if self.path == "/" or self.path == "/dashboard":
            self._send_html(DASHBOARD_HTML)
        elif self.path == "/health":
            self.load_cfg()
            s = {}
            for p, k in self.upstream_keys.items():
                s[p] = f"{len(k)}个Key" if k else "未配置"
            self._send_json({"status": "ok", "providers": s, "models": list(self.model_routes.keys())})
        elif self.path == "/v1/models":
            self.load_cfg()
            self._send_json({"object": "list", "data": [{"id": m, "object": "model"} for m in self.model_routes]})
        elif self.path.startswith("/favicon"):
            self.send_response(204)
            self.end_headers()
        else:
            self._send_json({"error": "Not found"}, 404)

    def do_POST(self):
        self.load_cfg()

        # === 管理API ===
        if self.path == "/admin/start":
            # 启动自身的新实例
            try:
                pid = os.fork()
                if pid == 0:
                    # 子进程
                    os.setsid()
                    with open(LOG_FILE, "a") as log:
                        log.write(f"\n{time.ctime()}: 仪表盘触发启动\n")
                    os.execv(sys.executable, [sys.executable, __file__])
                else:
                    with open(PID_FILE, "w") as f:
                        f.write(str(pid))
                    self._send_json({"status": "started", "pid": pid})
            except Exception as e:
                # fork不可用，用subprocess
                try:
                    proc = subprocess.Popen(
                        [sys.executable, __file__],
                        stdout=open(LOG_FILE, "a"), stderr=subprocess.STDOUT,
                        start_new_session=True
                    )
                    with open(PID_FILE, "w") as f:
                        f.write(str(proc.pid))
                    self._send_json({"status": "started", "pid": proc.pid})
                except Exception as e2:
                    self._send_json({"status": "error", "error": str(e2)}, 500)

        elif self.path == "/admin/stop":
            # 停止服务
            try:
                with open(PID_FILE) as f:
                    pid = int(f.read().strip())
                os.kill(pid, signal.SIGTERM)
                self._send_json({"status": "stopped"})
            except:
                self._send_json({"status": "already_stopped"})

        elif self.path == "/admin/restart":
            # 重启：先停再起
            try:
                with open(PID_FILE) as f:
                    old_pid = int(f.read().strip())
                os.kill(old_pid, signal.SIGTERM)
                time.sleep(1)
            except:
                pass

            try:
                proc = subprocess.Popen(
                    [sys.executable, __file__],
                    stdout=open(LOG_FILE, "a"), stderr=subprocess.STDOUT,
                    start_new_session=True
                )
                with open(PID_FILE, "w") as f:
                    f.write(str(proc.pid))
                self._send_json({"status": "restarted", "pid": proc.pid})
            except Exception as e:
                self._send_json({"status": "error", "error": str(e)}, 500)

        # === API中转 ===
        elif self.path == "/v1/chat/completions":
            if not self.check_auth():
                self._send_json({"error": "无效Token"}, 401)
                return

            data = self._read_body()
            model_name = data.get("model", "")
            messages = data.get("messages", [])

            # 路由解析
            upstream = None
            for prefix, route in self.model_routes.items():
                if model_name.startswith(prefix):
                    key = self.get_key(route["provider"])
                    if not key:
                        self._send_json({"error": f"上游 {route['provider']} 未配置Key"}, 400)
                        return
                    upstream = {
                        "base_url": route["base_url"],
                        "api_key": key,
                        "model": route.get("model", model_name),
                    }
                    break

            if not upstream:
                self._send_json({"error": f"未找到模型 {model_name}"}, 400)
                return

            # 转发请求
            url = upstream["base_url"] + "/chat/completions"
            headers = {
                "Authorization": f"Bearer {upstream['api_key']}",
                "Content-Type": "application/json",
            }
            payload = {
                "model": upstream["model"],
                "messages": messages,
                "max_tokens": data.get("max_tokens", 2048),
                "temperature": data.get("temperature", 0.7),
                "stream": False,
            }

            try:
                resp = http_requests.post(url, headers=headers, json=payload, timeout=120)
                self._send_json(resp.json(), resp.status_code)
            except Exception as e:
                self._send_json({"error": f"上游调用失败: {str(e)}"}, 502)

        else:
            self._send_json({"error": "Not found"}, 404)

    def do_OPTIONS(self):
        self.send_response(200)
        self.send_header("Access-Control-Allow-Origin", "*")
        self.send_header("Access-Control-Allow-Methods", "GET,POST,OPTIONS")
        self.send_header("Access-Control-Allow-Headers", "*")
        self.end_headers()

    def log_message(self, format, *args):
        pass  # 静默


# ====== 主入口 ======
def main():
    # 写PID
    with open(PID_FILE, "w") as f:
        f.write(str(os.getpid()))

    server = HTTPServer(("0.0.0.0", PORT), RelayHandler)
