    <script>
        // ====== 全局状态 ======
        let cameraActive = false;
        let faceMesh = null;
        let scene, camera, renderer, model, mixer, clock;
        let currentExpression = 'neutral';
        const expressions = {
            happy: { mouth: 0.8, eye: 0.3 },
            think: { mouth: 0.2, eye: 0.1 },
            surprise: { mouth: 1.0, eye: 0.5 },
            angry: { mouth: 0.4, eye: -0.2 },
            neutral: { mouth: 0.0, eye: 0.0 }
        };

        // ====== 3D场景初始化 ======
        function init3D() {
            scene = new THREE.Scene();
            scene.background = new THREE.Color(0x050510);

            camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
            camera.position.set(0, 1.2, 2.5);

            renderer = new THREE.WebGLRenderer({ antialias: true });
            renderer.setSize(document.getElementById('arona3d').offsetWidth, document.getElementById('arona3d').offsetHeight);
            renderer.shadowMap.enabled = true;
            document.getElementById('arona3d').appendChild(renderer.domElement);

            // 光源
            const ambient = new THREE.AmbientLight(0x404040);
            scene.add(ambient);
            const dirLight = new THREE.DirectionalLight(0xffffff, 1);
            dirLight.position.set(5, 5, 5).normalize();
            scene.add(dirLight);

            // 加载临时模型 (placeholder)
            const geometry = new THREE.BoxGeometry(1, 1, 1);
            const material = new THREE.MeshStandardMaterial({ 
                color: 0x4488ff,
                emissive: 0x2244aa,
                metalness: 0.5,
                roughness: 0.5
            });
            model = new THREE.Mesh(geometry, material);
            model.position.y = 0.5;
            scene.add(model);

            clock = new THREE.Clock();

            animate();
            updateModelStatus("✅ 加载了占位立方体 (等待猫娘.glb模型)");
        }

        // ====== 动画循环 ======
        function animate() {
            requestAnimationFrame(animate);
            if (mixer) mixer.update(clock.getDelta());
            if (model && currentExpression === 'think') {
                model.rotation.y += 0.01; // 思考时小旋转
            }
            renderer.render(scene, camera);
        }

        // ====== 摄像头追踪 ======
        function startCameraTracking() {
            const video = document.getElementById('cameraVideo');
            navigator.mediaDevices.getUserMedia({ video: true, audio: false })
                .then(stream => {
                    video.srcObject = stream;
                    cameraActive = true;
                    updateCameraStatus("📡 面部追踪中…");
                    document.getElementById('btnStartCamera').disabled = true;
                    document.getElementById('btnStopCamera').disabled = false;

                    // 初始化 MediaPipe Face Mesh (简化版)
                    setTimeout(() => {
                        addChatMessage("system", "🎭 面部追踪已启动！试试做出不同表情～");
                        simulateFaceTracking(); // 模拟面部数据
                    }, 1000);
                })
                .catch(err => {
                    addChatMessage("system", `❌ 摄像头错误: ${err.message}`);
                });
        }

        function stopCameraTracking() {
            const video = document.getElementById('cameraVideo');
            if (video.srcObject) {
                video.srcObject.getTracks().forEach(track => track.stop());
                video.srcObject = null;
            }
            cameraActive = false;
            updateCameraStatus("📷 摄像头已关闭");
            document.getElementById('btnStartCamera').disabled = false;
            document.getElementById('btnStopCamera').disabled = true;
        }

        // ====== 模拟面部数据 ======
        function simulateFaceTracking() {
            if (!cameraActive) return;
            // 随机模拟面部变化
            const expressions = ['neutral', 'happy', 'think', 'surprise'];
            const randomExp = expressions[Math.floor(Math.random() * expressions.length)];
            if (randomExp !== currentExpression) {
                aronaExpression(randomExp);
            }
            setTimeout(simulateFaceTracking, 2000 + Math.random() * 3000);
        }

        // ====== 表情控制 ======
        function aronaExpression(name) {
            currentExpression = name;
            const exp = expressions[name] || expressions.neutral;

            // 更新模型表情 (placeholder)
            if (model) {
                model.scale.set(1 + exp.mouth * 0.1, 1 + exp.eye * 0.1, 1);
                model.material.emissive.setHex(exp.mouth > 0.5 ? 0x4466aa : 0x2244aa);
            }

            const expNames = { happy: "😊 开心", think: "🤔 思考", surprise: "😯 惊讶", angry: "😠 生气", neutral: "😐 平静" };
            updateModelStatus(`🎭 表情: ${expNames[name]}`);
            addChatMessage("arona", `切换为「${expNames[name]}」表情~`);
        }

        // ====== 聊天功能 ======
        function addChatMessage(sender, text) {
            const log = document.getElementById('chatLog');
            const msg = document.createElement('div');
            msg.style.marginBottom = '6px';
            msg.style.color = sender === 'arona' ? '#88aaff' : '#aaffaa';
            msg.textContent = `🐱 ${sender === 'arona' ? '阿罗娜' : '你'}: ${text}`;
            log.appendChild(msg);
            log.scrollTop = log.scrollHeight;
        }

        function sendMessage() {
            const input = document.getElementById('chatInput');
            const text = input.value.trim();
            if (!text) return;

            addChatMessage("user", text);
            input.value = "";

            // 模拟回复
            setTimeout(() => {
                const replies = [
                    "喵～老师真有意思！",
                    "这个问题我需要思考一下……",
                    "正在搜索相关资料～",
                    "用代码解决的话可能是这样：",
                    "尾巴表示同意！🐾"
                ];
                const reply = replies[Math.floor(Math.random() * replies.length)];
                addChatMessage("arona", reply);
                aronaExpression(['happy', 'think'][Math.floor(Math.random() * 2)]);
            }, 800 + Math.random() * 1200);
        }

        // ====== 状态更新 ======
        function updateCameraStatus(text) {
            document.querySelector('.camera-status').textContent = text;
        }

        function updateModelStatus(text) {
            document.getElementById('modelStatus').textContent = text;
        }

        // ====== 事件绑定 ======
        document.getElementById('btnStartCamera').onclick = startCameraTracking;
        document.getElementById('btnStopCamera').onclick = stopCameraTracking;
        document.getElementById('chatInput').addEventListener('keydown', e => {
            if (e.key === 'Enter') sendMessage();
        });

        // ====== 启动 ======
        window.addEventListener('resize', () => {
            if (renderer) {
                renderer.setSize(document.getElementById('arona3d').offsetWidth, document.getElementById('arona3d').offsetHeight);
                camera.aspect = document.getElementById('arona3d').offsetWidth / document.getElementById('arona3d').offsetHeight;
                camera.updateProjectionMatrix();
            }
        });

        init3D();
    </script>
